// TH16 v1.00a Extra (s7) stage wave: MainSub02 -> two GirlD01 enemies.
// Source: st07.ecl.txt:1189-1194 (entry), GirlD01:710-734, GirlD01_at:736-758.
// Only rank 4 (Extra) is implemented; source section has no difficulty masks.

const TIME_LIMIT: int = 974;          // 120 opening buffer + 850 source estimate + 4 startup
const OPENING_BUFFER: int = 120;

// Approved TH16 type 8 slot (bullet-types.md; source etSprite(0, 8, 6)).
const TH16_RICE: int = 480;

// Source etAngle second parameter 0.12566371 rad per layer.
const LAYER_STEP_BAM: int = 1311;

// One source volley: etAim(0,3) ring, 25 lanes x 3 layers, base alpha,
// layer angles alpha + q*0.12566371, layer speeds 2.0/1.8/1.6.
// etEx(0,0,2,1,...) is ANIM a=1; the retained birth displacement is
// -4*velocity along each bullet's own angle = -8.0/-7.2/-6.4 px.
// Three sh_fire calls preserve per-layer speed and displacement; the
// annulus/lane set is identical to the source layer/lane product.
sub fire_volley(alpha: angle) {
    sh_speed(0, 2.0fx, 0fx);
    sh_angle(0, alpha, 0deg);
    sh_dist(0, -8.0fx);
    sh_fire(0);

    sh_speed(0, 1.8fx, 0fx);
    sh_angle(0, alpha + (LAYER_STEP_BAM as angle), 0deg);
    sh_dist(0, -7.2fx);
    sh_fire(0);

    sh_speed(0, 1.6fx, 0fx);
    sh_angle(0, alpha + ((2 * LAYER_STEP_BAM) as angle), 0deg);
    sh_dist(0, -6.4fx);
    sh_fire(0);
}

// GirlD01_at: wait(60), configure et 0, then 10 volleys 60 frames apart.
// $B=10 with `if ($B--) goto ...` fires B=10..1, then returns after one more wait.
async sub girl_attack() {
    wait(60);
    sh_reset(0);
    sh_sprite(0, TH16_RICE, 6);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_count(0, 25, 1);
    var alpha: angle = 90deg;
    for volley in 0..10 {
        fire_volley(alpha);
        alpha = alpha - 15deg;
        wait(60);
    }
}

// GirlD01: boxes, initial downward drop, async attack, then a slow drift
// toward the center after 240 frames; the source loops forever afterwards.
// Mirror=1 for enmCreateM: regular moveVel angles are reflected about x
// (pi - angle); etAngle/firing is not mirrored per enemy-state.md.
async sub girl_main(mirror: int) {
    set_invuln(65535);
    set_hurtbox(16fx);                 // setHurtbox(32,32): first value * 0.5
    set_hitbox(12fx);                  // setHitbox(24,24): first value * 0.5

    move_vel(0, 90deg, 2.7fx, EASE_LINEAR);
    move_speed(60, 0fx, EASE_QUAD_IN); // moveSpeedTime(60, mode1, 0.0)
    spawn girl_attack();

    wait(240);
    var drift: angle = 11.25deg;
    if mirror != 0 {
        drift = 168.75deg;
    }
    move_vel(0, drift, 0fx, EASE_LINEAR);
    move_speed(80, 0.7fx, EASE_QUAD_IN); // moveSpeedTime(80, mode1, 0.7)
    wait(60);
    loop { wait(1000); }
}

// MainSub02: enmCreate(-100,-48,...) + enmCreateM(100,-48,...).
// The source parent is the stage task at (0,0), so the world positions are
// the listed signed values; the second child carries mirror state 1.
async sub spawn_wave() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(-100fx, -48fx, 2000, 0, 0, 0, girl_main(0));
    _ = spawn_enemy(100fx, -48fx, 2000, 0, 0, 0, girl_main(1));
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, spawn_wave, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 2000, 0, 0, 0, control);
    loop { wait(600); }
}
